os.makedirs("/tmp/e3", exist_ok=True)
open("/tmp/e3/e3.cu","w").write(SRC)
nvcc = shutil.which("nvcc") or glob.glob("/usr/local/cuda*/bin/nvcc")[0]
t=time.time()
r = subprocess.run([nvcc,"-O3","-std=c++17","-gencode","arch=compute_100a,code=sm_100a","-shared","-Xcompiler","-fPIC","-o","/tmp/e3/e3.so","/tmp/e3/e3.cu","-lcuda"],capture_output=True,text=True)
print("build", r.returncode, round(time.time()-t,1), r.stderr[-1500:])
if r.returncode: sys.exit()
lib = ctypes.CDLL("/tmp/e3/e3.so")
lib.run_cfg.argtypes = [ctypes.c_void_p]*3 + [ctypes.c_int]*9
W = torch.randn(18432,3072,device='cuda'); E = torch.randn(1024,3072,device='cuda')
out = torch.zeros(148*4, dtype=torch.int64, device='cuda')
NK=384
def run(feed,mma,kbs,stages,E_rows,grid=148,reps=2):
    e1=min(E_rows,128); e2=E_rows-e1
    out.zero_()
    r = lib.run_cfg(W.data_ptr(),E.data_ptr(),out.data_ptr(),feed,mma,kbs,stages,e1,e2,NK,grid,reps)
    if r: return ("ERR",r)
    o = out.view(-1,4)[0::2].cpu().double()
    clk=(o[:,1]-o[:,0]); ns=(o[:,3]-o[:,2]); ok=ns>0
    if ok.sum()==0: return ("EMPTY",0)
    return (float(clk[ok].median())/NK, float((clk[ok]/ns[ok]).median())*1000)
def sbytes(kbs,E_rows): return kbs*(16384+E_rows*128)
def fit(kbs,E_rows,cap=99): return min(cap,(232000-1024)//sbytes(kbs,E_rows))
# smoke
for cfg in [(0,1,1,4,96),(1,0,1,4,192),(1,1,1,4,192)]:
    print("smoke",cfg,run(*cfg))
    torch.cuda.synchronize()

